#!/usr/bin/env python3
"""Mechanical checks of the solution scripts in code/<chapter>/*.py (standard library only).

Usage (from the repository root):
    code_deps.py make-deps    print a Makefile fragment: a script is re-run when any module it imports (transitively) or any file
                              of code/<chapter>/data/ that they name in a string (e.g. "pride_and_prejudice.zip") changes
    code_deps.py check        print the findings below, exit 1 if there is any
        - a script imports a third-party package outside the allowed list (numpy first, matplotlib for figures, ...)
        - a chapter names a script (`name.py`) that does not exist in code/
        - a file of code/<chapter>/data/ that no script names (unused), or a script that names a data file that is not there
        - the Makefile does not know exactly the dependencies of each script (it is asked with `make -pn`)
"""
from __future__ import annotations

import ast
import re
import subprocess
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
CODE = ROOT / "code"
CHAPTERS = ROOT / "chapters"

# numpy is the default. matplotlib draws the figures. sklearn only ships the bundled digits data set.
# Add a package here only when the book needs it, and say why in the script that imports it.
ALLOWED = {"numpy", "matplotlib", "sklearn"}
# Deep learning needs torch. Anything else needs a reason: add it here and say why in the script that imports it.
ALLOWED.add("torch")
# scipy: sparse co-occurrence matrices of a 17-million-word text, and the Spearman rank correlation (chapter "Likeness as Nearness").
ALLOWED.add("scipy")
STDLIB = set(sys.stdlib_module_names)


def scripts() -> list[Path]:
    return sorted(CODE.glob("*/*.py"))


def imported_modules(path: Path) -> set[str]:
    """Package names imported by `path` (import x.y -> x, from x.y import z -> x)."""
    names = set()
    for node in ast.walk(ast.parse(path.read_text(encoding="utf-8"))):
        if isinstance(node, ast.Import):
            names |= {a.name.split(".")[0] for a in node.names}
        elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
            names.add(node.module.split(".")[0])
    return names


def local_imports(path: Path) -> list[Path]:
    """Scripts of the same chapter directory that `path` imports (they run from their own directory)."""
    return sorted(p for p in (path.parent / f"{m}.py" for m in imported_modules(path)) if p.is_file() and p != path)


def transitive_imports(path: Path) -> list[Path]:
    seen: list[Path] = []
    todo = local_imports(path)
    while todo:
        p = todo.pop()
        if p not in seen:
            seen.append(p)
            todo += local_imports(p)
    return sorted(seen)


def data_files(path: Path) -> list[Path]:
    """Files of code/<chapter>/data/ whose name is a string of `path` (as in `Path(__file__).parent / "data" / "x.zip"`)."""
    strings = {n.value for n in ast.walk(ast.parse(path.read_text(encoding="utf-8"))) if isinstance(n, ast.Constant) and isinstance(n.value, str)}
    return sorted(f for f in (path.parent / "data").glob("*") if f.is_file() and f.name in strings)


DATA_SUFFIXES = {".zip", ".txt", ".csv", ".json", ".npy", ".npz", ".pkl", ".gz", ".tsv"}


def data_strings(path: Path) -> set[str]:
    """Strings of `path` that look like a data file name."""
    return {n.value for n in ast.walk(ast.parse(path.read_text(encoding="utf-8")))
            if isinstance(n, ast.Constant) and isinstance(n.value, str) and Path(n.value).suffix in DATA_SUFFIXES and "/" not in n.value}


def expected_deps(script: Path) -> set[Path]:
    deps = set(transitive_imports(script))
    return deps | {f for m in [script, *deps] for f in data_files(m)}


def makefile_deps() -> dict[str, set[str]] | None:
    """Explicit prerequisites that the Makefile gives to each `.code-tests/<chapter>/<name>.ok`, read from `make -pn` (None if make fails)."""
    try:
        out = subprocess.run(["make", "-pn", "--no-print-directory"], cwd=ROOT, capture_output=True, text=True, check=False).stdout
    except OSError:
        return None
    found: dict[str, set[str]] = {}
    for line in out.splitlines():
        m = re.match(r"^(\.code-tests/[^\s:%]+\.ok):\s*(.*)$", line)
        if m:
            found.setdefault(m.group(1), set()).update(m.group(2).split())
    return found


def make_deps() -> str:
    lines = ["# Generated by review-code/scripts/code_deps.py: do not edit."]
    for s in scripts():
        deps = transitive_imports(s)
        deps = sorted(set(deps) | {f for m in [s, *deps] for f in data_files(m)})
        if deps:
            stamp = Path(".code-tests") / s.relative_to(CODE).with_suffix(".ok")
            lines.append(f"{stamp}: " + " ".join(str(d.relative_to(ROOT)) for d in deps))
    return "\n".join(lines) + "\n"


def check() -> list[str]:
    findings = []
    names = {s.name for s in scripts()}
    for s in scripts():
        for m in sorted(imported_modules(s)):
            if m not in STDLIB and m not in ALLOWED and not (s.parent / f"{m}.py").is_file():
                findings.append(f"{s.relative_to(ROOT)}: imports '{m}', which is not in the allowed list {sorted(ALLOWED)}")
    for q in sorted(CHAPTERS.glob("*.qmd")):
        if q.name == "solutions.qmd":
            continue
        for n in sorted(set(re.findall(r"\b([a-z][a-z_0-9]*\.py)\b", q.read_text(encoding="utf-8")))):
            if n not in names:
                findings.append(f"{q.relative_to(ROOT)}: names {n}, which is not in code/*/")
    findings += check_data()
    findings += check_makefile()
    return findings


def check_data() -> list[str]:
    findings = []
    for chapter in sorted(p for p in CODE.glob("*") if p.is_dir()):
        used = {n for s in chapter.glob("*.py") for n in data_strings(s)}
        present = {f.name for f in (chapter / "data").glob("*") if f.is_file()}
        members = {m for f in (chapter / "data").glob("*.zip") if zipfile.is_zipfile(f) for m in zipfile.ZipFile(f).namelist()}  # inside archives
        findings += [f"{(chapter / 'data' / n).relative_to(ROOT)}: no script names this data file" for n in sorted(present - used)]
        for s in sorted(chapter.glob("*.py")):
            findings += [f"{s.relative_to(ROOT)}: names the data file {n}, which is not in {(chapter / 'data').relative_to(ROOT)}/ "
                         f"(if it is external, pin it with a SHA-256 checked in the code)" for n in sorted(data_strings(s) - present - members)]
    return findings


def check_makefile() -> list[str]:
    """The Makefile must give each script exactly the prerequisites found in its imports and data files (plus the shared helpers)."""
    actual = makefile_deps()
    if actual is None:
        return ["make could not be run, so the dependencies of the Makefile were not checked"]
    findings = []
    for s in scripts():
        if s.name == "utils.py" or s.read_text(encoding="utf-8").startswith("# SKELETON"):
            continue
        stamp = str(Path(".code-tests") / s.relative_to(CODE).with_suffix(".ok"))
        want = {str(d.relative_to(ROOT)) for d in expected_deps(s)}
        have = actual.get(stamp, set()) - {str(s.relative_to(ROOT))}
        helpers = {str(h.relative_to(ROOT)) for h in CODE.glob("*/utils.py")}
        if want - have:
            findings.append(f"Makefile: {stamp} does not depend on {sorted(want - have)}")
        if have - want - helpers:
            findings.append(f"Makefile: {stamp} depends on {sorted(have - want - helpers)}, which the script does not use")
    return findings


def main(argv: list[str]) -> int:
    if argv == ["make-deps"]:
        print(make_deps(), end="")
        return 0
    if argv == ["check"]:
        findings = check()
        print("\n".join(findings) if findings else "code: no findings")
        return 1 if findings else 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
